; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 14: Cls
			dw kw_cls

			; 15: Print "VB self test 11"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 18: Chk Add3(10), 13
			dw fn_add3, lit_10, var_add3_add3
			dw p_chk_c, var_add3_add3, lit_13

			; 19: a = 20
			dw kw_ltov, 20, var_a

			; 20: Chk Add3(a), 23
			dw fn_add3, var_a, var_add3_add3
			dw p_chk_c, var_add3_add3, lit_23

			; 21: Chk Add3(a * 2) + Add3(1), 47
			dw kw_2x, var_a, tmp0
			dw fn_add3, tmp0, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp0
			dw fn_add3, lit_1, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp1
			dw kw_add, tmp0, tmp1, tmp0
			dw p_chk_c, tmp0, lit_47

			; 22: Chk Add3(Add3(Add3(0))), 9
			dw fn_add3, lit_0, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp0
			dw fn_add3, tmp0, var_add3_add3
			dw kw_vtov, var_add3_add3, tmp0
			dw fn_add3, tmp0, var_add3_add3
			dw p_chk_c, var_add3_add3, lit_9

			; 25: a = Add3(5)
			dw fn_add3, lit_5, var_a

			; 26: Chk a, 8
			dw p_chk_c, var_a, lit_8

			; 27: a = Add3(a)
			dw fn_add3, var_a, var_add3_add3
			dw kw_vtov, var_add3_add3, var_a

			; 28: Chk a, 11
			dw p_chk_c, var_a, lit_11

			; 31: Chk AddXY(7, 8), 15
			dw fn_addxy, lit_7, lit_8, var_addxy_addxy
			dw p_chk_c, var_addxy_addxy, lit_15

			; 32: b = AddXY(a, 5) * 2
			dw fn_addxy, var_a, lit_5, var_addxy_addxy
			dw kw_vtov, var_addxy_addxy, tmp0
			dw kw_2x, tmp0, var_b

			; 33: Chk b, 32
			dw p_chk_c, var_b, lit_32

			; 36: c = 41
			dw kw_ltov, 41, var_c

			; 37: Inc c
			dw fn_inc, var_c

			; 38: Chk c, 42
			dw p_chk_c, var_c, lit_42

			; 39: Inc c
			dw fn_inc, var_c

			; 40: Inc c
			dw fn_inc, var_c

			; 41: Chk c, 44
			dw p_chk_c, var_c, lit_44

			; 44: s = "hello"
			dw kw_strcpy, var_s, str1

			; 45: UpFirst s
			dw fn_upfirst, var_s

			; 46: Chk Asc(s), 72
			dw kw_strasc, var_s, tmp0
			dw p_chk_c, tmp0, lit_72

			; 47: Chk Len(s), 5
			dw kw_strlen, var_s, tmp0
			dw p_chk_c, tmp0, lit_5

			; 50: n = Big(3)
			dw fn_big, lit_3, var_n

			; 51: Chk n \ 65536, 3
			dw kw_l_div, var_n, llit_65536, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_3

			; 52: Chk n Mod 65536, 0
			dw kw_l_mod, var_n, llit_65536, ltmp0
			dw kw_l_ltoi, ltmp0, tmp0
			dw p_chk_c, tmp0, lit_0

			; 55: Chk AddC(1), 4
			dw fn_addc, lit_1, var_addc_addc
			dw p_chk_c, var_addc_addc, lit_4

			; 58: Chk Twice(21), 42
			dw p_twice_c, lit_21
			dw p_chk_c, var_twice_twice, lit_42

			; 61: c = 0
			dw kw_ztov, var_c

			; 62: For i = 1 To 50
			dw kw_ltov, 1, var_i
for1_t:

			; 63: Inc c
			dw fn_inc, var_c

			; 64: Next
			dw kw_next1l_n, var_i, 50, for1_t
for1_e:

			; 65: Chk c, 50
			dw p_chk_c, var_c, lit_50

			; 67: Print
			dw kw_printnl

			; 68: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str2
			dw kw_printint, var_bad
			dw kw_printstrvar, str3
			dw kw_printnl

			; 69: End
			dw kw_printnl0
			dw kw_printstrvar, str4
			dw kw_waitkey
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 72: t = t + 1
			dw kw_inc, var_t

			; 73: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str5

			; 74: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if2_1

			; 75: Print "ok ";
			dw kw_printstrvar, str6

			; 76: Else
			dw if2_e_go
if2_1:

			; 77: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str7
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str8

			; 78: bad = bad + 1
			dw kw_inc, var_bad

			; 79: End If
if2_e:
			dw p_chk_r

; ============================================================
; function twice (normal mode)
; ============================================================

p_twice:

			; 177: #asm
			dw asm_0_177_n
			dw p_twice_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_e_go:			ld sp, if2_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_twice_c:		; call twice (normal)
			pop hl			; x
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_twice_x), de
			ld hl, 0
			ld (var_twice_twice), hl
			ld (p_twice_rs), sp
			ld sp, p_twice
			jp ntc_xn
p_twice_r:		; end of twice
			ld sp, (p_twice_rs)
			jp ntc_xn

; ============================================================
; Inline assembly (#asm ... #endasm)
; ============================================================

fn_add3:		; function add3 (asm keyword), main.bas line 83
    pop hl          ; address of x [84]
    ld e,(hl)		; main.bas 85
    inc hl		; main.bas 86
    ld d,(hl)		; main.bas 87
    inc de		; main.bas 88
    inc de		; main.bas 89
    inc de		; main.bas 90
    pop hl          ; address of the result [91]
    ld (hl),e		; main.bas 92
    inc hl		; main.bas 93
    ld (hl),d		; main.bas 94
			ret			; end of #asm

fn_addxy:		; function addxy (asm keyword), main.bas line 99
    pop hl          ; x [100]
    ld e,(hl)		; main.bas 101
    inc hl		; main.bas 102
    ld d,(hl)		; main.bas 103
    pop hl          ; y [104]
    ld a,(hl)		; main.bas 105
    inc hl		; main.bas 106
    ld h,(hl)		; main.bas 107
    ld l,a		; main.bas 108
    add hl,de		; main.bas 109
    ex de,hl		; main.bas 110
    pop hl          ; result [111]
    ld (hl),e		; main.bas 112
    inc hl		; main.bas 113
    ld (hl),d		; main.bas 114
			ret			; end of #asm

fn_inc:		; sub inc (asm keyword), main.bas line 119
    pop hl          ; address of v (ByRef: write through it) [120]
    inc (hl)		; main.bas 121
    jr nz,fn_inc_done		; main.bas 122
    inc hl		; main.bas 123
    inc (hl)		; main.bas 124
fn_inc_done:		; main.bas 125
			ret			; end of #asm

fn_upfirst:		; sub upfirst (asm keyword), main.bas line 130
    pop hl          ; the string itself (0 terminated) [131]
    ld a,(hl)		; main.bas 132
    cp 'a'		; main.bas 133
    ret c		; main.bas 134
    cp 'z'+1		; main.bas 135
    ret nc		; main.bas 136
    sub 32		; main.bas 137
    ld (hl),a		; main.bas 138
			ret			; end of #asm

fn_big:		; function big (asm keyword), main.bas line 143
    pop hl          ; hi [144]
    ld e,(hl)		; main.bas 145
    inc hl		; main.bas 146
    ld d,(hl)		; main.bas 147
    pop hl          ; result: 4 bytes, low word first [148]
    xor a		; main.bas 149
    ld (hl),a		; main.bas 150
    inc hl		; main.bas 151
    ld (hl),a		; main.bas 152
    inc hl		; main.bas 153
    ld (hl),e		; main.bas 154
    inc hl		; main.bas 155
    ld (hl),d		; main.bas 156
			ret			; end of #asm

fn_addc:		; function addc (asm keyword), main.bas line 161
    pop hl		; main.bas 162
    ld e,(hl)		; main.bas 163
    inc hl		; main.bas 164
    ld d,(hl)		; main.bas 165
    ld hl,3		; main.bas 166
    add hl,de		; main.bas 167
    ex de,hl		; main.bas 168
    pop hl		; main.bas 169
    ld (hl),e		; main.bas 170
    inc hl		; main.bas 171
    ld (hl),d		; main.bas 172
			ret			; end of #asm

asm_0_177_n:		; #asm, main.bas line 177 (normal)
    ld hl,(var_twice_x)		; main.bas 178
    add hl,hl		; main.bas 179
    ld (var_twice_twice),hl		; main.bas 180
			ret			; end of #asm


; ============================================================
; Variables
; ============================================================

var_add3_add3:			dw 0
var_a:			dw 0
var_addxy_addxy:			dw 0
var_b:			dw 0
var_c:			dw 0
			db 40			; capacity
var_s:			ds 41
var_n:			dw 0, 0
var_addc_addc:			dw 0
var_twice_twice:			dw 0
var_i:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_twice_rs:			dw 0
var_twice_x:			dw 0
tmp0:			dw 0
tmp1:			dw 0
ltmp0:			dw 0, 0

; numbers passed by address (read only)
lit_10:			dw 10
lit_13:			dw 13
lit_23:			dw 23
lit_1:			dw 1
lit_47:			dw 47
lit_0:			dw 0
lit_9:			dw 9
lit_5:			dw 5
lit_8:			dw 8
lit_11:			dw 11
lit_7:			dw 7
lit_15:			dw 15
lit_32:			dw 32
lit_42:			dw 42
lit_44:			dw 44
lit_72:			dw 72
